use vstd::prelude::*;

verus! {

fn swap_first_and_last(a: &Vec<i32>) -> (result: Vec<i32>)
    requires
        a.len() > 0,
    ensures
        result.len() == a.len(),
        // first and last swapped (covers len == 1 case too)
        result[0] == a[a.len() - 1],
        result[result.len() - 1] == a[0],
        // interior unchanged
        forall|i: int|
            1 <= i && i < a.len() as int - 1 ==> result[i] == a[i],
{
    let n = a.len();

    // Start with a full copy so interior elements are already correct.
    let mut result = a.clone();

    if n == 1 {
        // For length 1, swapping does nothing; ensures already follow.
        return result;
    }

    // Now overwrite just the first and last positions.
    let first = a[0];
    let last = a[n - 1];

    result[0] = last;
    result[n - 1] = first;

    // Help the prover with the interior property: clone preserves all indices.
    assert(forall|i: int|
        1 <= i && i < n as int - 1 ==> result[i] == a[i]
    ) by {
        assert(forall|i: int|
            0 <= i && i < n as int ==> a.clone()[i] == a[i]
        );
    };

    result
}

} // verus!

